module hol {
    theory InternalEquality {
        include .base_languages.InternalLogic
        include .equality.TypedEquality
        include .function_types.SimpleFunctions

        equalConstant: A -> tm A -> tm (A → boolean)
        equalConstant = A -> x -> simplambda(A, boolean) (y -> tequal(A, x, y))
    }

    theory IHOL {
        include InternalEquality
        include .booleans.InternalTruthValues
        include .sfol.ISFOL
    }

    theory IHOLND {
        include InternalEquality
        include .sfol.ISFOLND
        include .equality.PropositionalExtensionality

        eq_equiv: (F,G) -> ded tequal(boolean, F, G) -> ded (F⇔G)
        equiv_eq: (F,G) -> ded (F⇔G) -> ded tequal(boolean, F, G)
        eq_thm: (F,G) -> ded tequal(boolean, F, G) -> ded F -> ded G
        thm_true: F -> ded F -> ded tequal(boolean, F, truth)
        true_thm: F -> ded tequal(boolean, F, truth) -> ded F
    }

    theory HOL {
        include IHOL
    }

    theory HOLND {
        include HOL
        include IHOLND
        include .sfol.SFOLND
        include .function_types.SimpleFunctionsEta
    }

    theory PowerHOLND {
        include HOLND

        // realize powertypes.PowerTypes
        power: tp -> tp
        power = a -> a → boolean

        pfilter: (A, tm (A → boolean)) -> tm (power A)
        pfilter = (A, P) -> P

        iin: (A, tm A, tm (power A)) -> prop
        iin = (A, x, S) -> simpapply(A, boolean) S x

        compute: (A, P, x) -> ded tequal(boolean, iin(A, x, pfilter(A, P)), simpapply(A, boolean) P x)
        expand: (A, S) -> ded tequal(power A, S, pfilter(A, simplambda(A, boolean) (x -> iin(A, x, S))))
    }

    // Diaconescu's theorem, following the Wikipedia article
    theory ClassicalViaChoice {
        include HOLND
        include .sfol.TypedChoice

        Forbot: prop -> tm boolean -> prop
        Forbot = F -> x -> F ∨ tequal(boolean, x, falsity)

        exists_Forbot: F -> ded (texists boolean (Forbot F))

        Fortop: prop -> tm boolean -> prop
        Fortop = F -> x -> F ∨ tequal(boolean, x, truth)

        exists_Fortop: F -> ded (texists boolean (Fortop F))

        tnd: F -> ded (F ∨ (¬F))
    }

    theory IfThenElseViaChoice {
        include HOLND
        include .sfol.TypedTotalChoice

        // realize .ifte.IfThenElse

        ifte_prop: (A) -> prop -> tm A -> tm A -> tm A -> prop
        ifte_prop = A -> b -> x -> y -> u -> (b ∧ tequal(A, u, x)) ∨ ((¬b) ∧ tequal(A, u, y))

        ifte: (A) -> prop -> tm A -> tm A -> tm A
        ifte = A -> b -> x -> y -> tany boolean (u -> ifte_prop A b x y u)

        ifte_exists: (A, B, X, Y) -> ded (texists A (u -> ifte_prop A B X Y u))
        ifte_unique: (A, B, X, Y, u) -> ded (ifte_prop A B X Y u) -> (v) -> ded (ifte_prop A B X Y v) -> ded tequal(A, u, v)
        ifte_true: (A, B, X, Y) -> ded B -> ded tequal(A, ifte A B X Y, X)
        ifte_false: (A, B, X, Y, P) -> ded (¬B) -> ded tequal(A, ifte A B X Y, Y)
    }
}

